/**
 * The words on and under the screenshots — what each screen shows, the
 * description a reader that cannot see the picture hears, and each numbered
 * spot (`hotspots.ts`) — in every language the site speaks. English is the
 * screenshots' own (`shared/shots.json`, `hotspots.ts`); a spot is found by
 * its English title. What the application itself labels — SAFE, Shuffle,
 * the activities, presets and workspaces — stays as the application shows it.
 */

import type { Shot } from "../../signal/shots";
import type { Spot } from "../hotspots";
import { fill } from "./sections";
import type { Lang } from "./strings";

export interface ScreensWords {
  /** What each screen shows, by the screen's name. */
  shows: Record<string, string>;
  /** A picture's description: what it shows, in which theme. */
  alt: string;
  /** The same, for a picture with a skin worn over the theme. */
  altSkin: string;
  /** Each spot, by its English title: its title and its sentence. */
  spots: Record<string, [string, string]>;
}

